t.M("מהי סיבת המוות העיקרית בחולי RA?", ["ILD", "זיהומים", "מחלה קרדיווסקולרית", "לימפומה"], 2)
t.F("מהו גורם הסיכון הסביבתי החזק ביותר ל-RA, ואיזה אלל גנטי קשור?", "עישון. HLA-DRB1 (shared epitope).")
t.F("איזה סיבוך עמוד שדרה חשוב לזכור בחולה RA לפני אינטובציה?", "אי-יציבות אטלנטו-אקסיאלית (C1-C2 subluxation).")
t.M("אילו מפרקים בדרך כלל אינם מעורבים ב-RA?", ["MCP", "PIP", "DIP", "שורש כף היד"], 2, "DIP אופייני לאוסטאוארטריטיס (Heberden) ולפסוריאטיק ארתריטיס.")
t.F("מה צריך לבדוק לפני התחלת anti-TNF?", "שחפת סמויה (IGRA או מנטו, וצילום חזה) והפטיטיס B.")
