t.N("EULAR/ACR 2019: מהו טיטר ה-ANA המינימלי (1:X) לקריטריון הכניסה? הקלד את X.", 80, 0, "")
t.N("EULAR/ACR 2019: כמה נקודות נדרשות לאבחנת SLE?", 10, 0, "נקודות")
